command:
set -e; PID=$(systemctl --user show omega-chatgpt-mcp.service -p MainPID --value); echo MCP_PID=$PID; python3 - "$PID" <<'PY'
import sys
pid=sys.argv[1]
data=open(f'/proc/{pid}/environ','rb').read().split(b'\0')
keys=[]
for x in data:
    if b'=' in x:
        k=x.split(b'=',1)[0].decode(errors='replace')
        if k.startswith(('GITHUB','GH_','OMEGA_')): keys.append(k)
for k in sorted(set(keys)): print(k)
PY
if command -v gh >/dev/null 2>&1; then echo GH_BIN=yes; if gh auth status >/dev/null 2>&1; then echo GH_AUTH=ok; else echo GH_AUTH=not_ok; fi; else echo GH_BIN=no; fi
